const [sessionSnapshot, setSessionSnapshot] = useState<SessionSnapshot>({ location, version: 0, state: { kind: "checking" } })
const currentSnapshot = sessionSnapshot.location === sessionLocation && sessionSnapshot.version === sessionVersion
const sessionState: SessionState = currentSnapshot ? sessionSnapshot.state : { kind: "checking" }

const missingRoute = route.kind === "not-found" || route.kind === "admin-denied"
const terminal = sessionState.kind === "unavailable" || (sessionState.kind === "authenticated" && missingRoute)
const terminalTitle = sessionState.kind === "unavailable" ? "Workspace unavailable"
  : route.kind === "admin-denied" ? "Administrator access required" : "Page not found"
const terminalMain = useRoutePresentation(terminal, `${terminalTitle} · AmuseMe`)

{sessionState.kind === "authenticated" && (route.kind === "document"
  ? <DocumentPage id={route.documentId} onUnauthenticated={onUnauthenticated} />
  : missingRoute
    ? <NotFoundPage main={terminalMain} adminDenied={route.kind === "admin-denied"} />
    : <Dashboard ownerId={sessionState.session.user.id} storedAttempt={uploadAttempt} setAttempt={setUploadAttempt}
      onUnauthenticated={onUnauthenticated} />)}

function LibraryMasthead({ count, loading, onRefresh }: { readonly count: number | null; readonly loading: boolean; readonly onRefresh: () => void }) {
  return <header className="library-masthead"><div><p className="library-eyebrow">Reading room</p><h2>Your library</h2></div>
    <div className="library-index">{count !== null && <span>{countLabel(count, "document")}</span>}
      <button className="library-secondary-link" type="button" disabled={loading} onClick={onRefresh}>Refresh</button></div></header>
}

type DropzoneProps = {
  readonly policy: UploadPolicy
  readonly uploading: boolean
  readonly enabled: boolean
  readonly primary: boolean
  readonly onFiles: (files: ReadonlyArray<File>) => void
}

const leftDropzone = (event: DragEvent<HTMLElement>): boolean =>
  !event.currentTarget.contains(event.relatedTarget instanceof Node ? event.relatedTarget : null)

function UploadDropzone({ policy, uploading, enabled, primary, onFiles }: DropzoneProps) {
  const [dragging, setDragging] = useState(false)
  const input = useRef<HTMLInputElement>(null)
  const dragOver = (event: DragEvent<HTMLElement>) => {
    event.preventDefault()
    event.dataTransfer.dropEffect = enabled ? "copy" : "none"
    if (enabled) setDragging(true)
  }
  const drop = (event: DragEvent<HTMLElement>) => { event.preventDefault(); setDragging(false); onFiles(Array.from(event.dataTransfer.files)) }
  const choose = (event: ChangeEvent<HTMLInputElement>) => { onFiles(Array.from(event.currentTarget.files ?? [])); event.currentTarget.value = "" }
  return <div className={`dropzone library-drop${dragging ? " dragging" : ""}`} role="group" aria-label="Document upload" aria-busy={uploading}
    onDragOver={dragOver} onDragLeave={(event) => { if (leftDropzone(event)) setDragging(false) }} onDrop={drop}>
    <div className="library-add-copy"><span className="library-add-icon"><DocumentIcon /></span>
      <div><h2 id="library-upload-title">{uploading ? "Uploading your document…" : "Add a document"}</h2>
        <p id="upload-limits">Drop one English-language PDF here, up to {formatBytes(policy.maxBytes)} and {policy.maxPages} pages.
          Short documents work best: a four-page PDF takes about five minutes.</p></div></div>
    <button className={`button${primary ? " primary" : ""}`} type="button" disabled={!enabled} aria-describedby="upload-limits"
      onClick={() => input.current?.click()}>Choose a file</button>
    <input ref={input} className="visually-hidden" aria-hidden="true" tabIndex={-1} type="file" accept="application/pdf,.pdf"
      disabled={!enabled} onChange={choose} />
  </div>
}

type FailureProps = {
  readonly attempt: UploadAttempt
  readonly ready: boolean
  readonly dismissable: boolean
  readonly onRetry: () => void
  readonly onDismiss: () => void
}

function UploadFailure({ attempt, ready, dismissable, onRetry, onDismiss }: FailureProps) {
  return <section className="message error" role="alert"><p>{attempt.file.name}: {attempt.message}</p>
    {attempt.state === "uncertain" && <p>The upload may already be saved. Check your library. Retrying uses the same submission identifier.</p>}
    <div className="document-actions"><button className="button" type="button" disabled={!ready} onClick={onRetry}>Retry upload</button>
      <button className="button" type="button" disabled={!dismissable} onClick={onDismiss}>Choose another file</button></div></section>
}

const uploadDisclosure = "Your page images are sent to Meta for extraction and checking. Document text and figure regions are sent to Meta"
  + " for headings, descriptions, and your reading guide. Local documents and outputs are kept for 7 days. You can delete them after processing stops."
const tooLongUpload = "This PDF is longer than AmuseMe can process in one run. Choose a shorter PDF, or save an excerpt of a few pages and upload that."
const interruptedUpload = "Upload interrupted. Check your documents, then retry this upload with its original submission identifier if needed."

type DashboardProps = {
  readonly ownerId: string
  readonly storedAttempt: UploadAttempt | null
  readonly setAttempt: Dispatch<SetStateAction<UploadAttempt | null>>
  readonly onUnauthenticated: () => void
}
type ListResult = { readonly version: number; readonly data: typeof DocumentList.Type | null; readonly error: string | null }

export function Dashboard({ ownerId, storedAttempt, setAttempt, onUnauthenticated }: DashboardProps) {

setAttempt((current) => current?.ownerId === ownerId && current.state === "pending"
  ? { ...current, state: "uncertain", message: interruptedUpload }
  : current)

const records = result.data?.documents ?? []
const hasPapers = records.length > 0
const refresh = () => setVersion((value) => value + 1)
const enabledPolicy = policy?.availability._tag === "enabled" ? policy : undefined
const showLibrary = !loading && result.data !== null && (hasPapers || result.error === null)
const controls = { retryEnabled: result.error === null, onDeleted: refresh, onRefresh: refresh, onUnauthenticated }
return <main className="dashboard-page reading-library" id="main-content" ref={main} tabIndex={-1}>
  <LibraryIntro />
  {enabledPolicy !== undefined && <section className="library-upload" aria-labelledby="library-upload-title">
    <UploadDropzone policy={enabledPolicy} uploading={uploading} enabled={chooseEnabled} primary onFiles={selectFiles} />
    {enabledPolicy.mode !== "fixture" && <p className="upload-disclosure">{uploadDisclosure}</p>}
  </section>}
  {message !== null && attempt === null && <p className="message" role="status">{message}</p>}
  {uploading && <p className="message" role="status">
    Uploading {attempt?.file.name ?? "your PDF"}. Keep this page open while the server checks and saves it.</p>}
  {attempt !== null && !uploading && <UploadFailure attempt={attempt} ready={ready} dismissable={!loading && !refreshingFailed}
    onRetry={() => submit(attempt.file, attempt)} onDismiss={() => { setAttempt(null); setMessage(null) }} />}
  <LibraryMasthead count={result.data === null ? null : records.length} loading={loading} onRefresh={refresh} />
  {loading && <p className="library-note" role="status">Loading your documents…</p>}
  {result.error !== null && <p className="message error" role="alert">{result.error}
    {" "}{result.data !== null && "The last saved list is shown. Its status may be out of date."}
    {" "}<button className="text-button" type="button" onClick={refresh}>Try again</button></p>}
  {showLibrary && <PaperLibrary records={records} controls={controls} />}
  {policy?.availability._tag === "disabled" && <section className="library-upload-unavailable" aria-label="Document upload"><h2>Uploads paused</h2>
    <p role="status">{uploadUnavailableMessage(policy.availability, hasPapers)}</p></section>}

const pages = Array.from({ length: record?.document.pageCount ?? 1 }, (_, index) => ({ pageNumber: index + 1 }))
const page = pageFromLocation(location, pages)
const route = guideRouteFromLocation(location)
const previousMode = useRef(route.mode)
useEffect(() => {
  if (!current || ownsOutput) return
  if (previousMode.current !== route.mode && main.current !== null) focusReadingPage(main.current)
  previousMode.current = route.mode
}, [current, ownsOutput, route.mode, main, previousMode])
const refresh = () => setVersion((value) => value + 1)
if (ownsOutput && record !== null && record.currentRevisionId !== null) {
  const revisionId = record.currentRevisionId
  return <ReaderWorkspace key={`${id}-${revisionId}`} record={record} revisionId={revisionId} onRefresh={refresh} onUnauthenticated={onUnauthenticated} />
}
const status = record !== null && summary !== null && result.error?.status !== 410 ? { record, summary } : null
return <main className="dashboard-page" id="main-content" ref={main} tabIndex={-1}>
  <InternalLink className="back-link" href="/"><span aria-hidden="true">←</span> Your library</InternalLink>

{current && result.error !== null && <><DocumentReadError error={result.error} onRetry={refresh} />
  {record !== null && result.error.status !== 410 && <p className="reader-small">The last saved status is shown and may be out of date.</p>}</>}
{status !== null && route.mode !== "read" && <div className="guide-choice-layout">
  <GoalChoices selected={selectedGoal(route)} processing={activeRun(status.record.latestRun)} ready={false}
    onSelect={(goal) => navigate(guideLocation(id, { mode: "choices", goal }, page))} onOpen={() => navigate(guideLocation(id, { mode: "read" }, page))} />
  <PaperStatus record={status.record} /></div>}
{status !== null && route.mode === "read" && <LiveDocument record={status.record} summary={status.summary} pages={pages} page={page} />}
{record !== null && result.error === null && <RetryDocumentControl record={record} onRefresh={refresh} onUnauthenticated={onUnauthenticated} />}

export const focusSourceQuote = (element: HTMLElement): void => Effect.runSync(Effect.sync(() => {
  element.focus({ preventScroll: true })
  element.querySelector("mark")?.scrollIntoView({ block: "center", inline: "nearest", behavior: "instant" })

export const focusMapNode = (element: HTMLElement): void => Effect.runSync(Effect.sync(() => {
  element.focus({ preventScroll: true })
  element.scrollIntoView({ block: "nearest", inline: "nearest", behavior: "instant" })
}))

export const observeWidth = (element: HTMLElement, onWidth: (width: number) => void): (() => void) => Effect.runSync(Effect.sync(() => {
  const observer = new ResizeObserver((entries) => { const entry = entries[0]; if (entry !== undefined) onWidth(entry.contentRect.width) })
  observer.observe(element)
  return () => Effect.runSync(Effect.sync(() => observer.disconnect()))
}))

const interactiveTargets = "a, button, input, textarea, select, summary, dialog, [contenteditable]"
const plainArrow = (event: KeyboardEvent): boolean =>
  !event.altKey && !event.ctrlKey && !event.metaKey && !event.shiftKey && (event.key === "ArrowLeft" || event.key === "ArrowRight")
const guideKeyHandler = (turn: (delta: number) => void) => (event: KeyboardEvent) => {
  if (!plainArrow(event)) return
  if (event.target instanceof Element && event.target.closest(interactiveTargets)) return
  if (document.querySelector("dialog[open]") !== null) return
  event.preventDefault()
  turn(event.key === "ArrowLeft" ? -1 : 1)
}

export const subscribeGuideKeys = (turn: (delta: number) => void): (() => void) => Effect.runSync(Effect.sync(() => {
  const onKey = guideKeyHandler(turn)
  document.addEventListener("keydown", onKey)
  return () => Effect.runSync(Effect.sync(() => document.removeEventListener("keydown", onKey)))
}))

export const makeRoutePresenter = () => {
  let observedPathname: string | undefined
  let focusPending = true
  const observePathname = (): void => {
    const pathname = window.location.pathname
    if (observedPathname === pathname) return
    observedPathname = pathname
    focusPending = true
  }
  const present = (element: HTMLElement, pathname: string, title: string): void => Effect.runSync(Effect.sync(() => {
    observePathname()
    if (!element.isConnected || window.location.pathname !== pathname) return
    document.title = title
    if (!focusPending) return
    focusPending = false
    element.focus({ preventScroll: true })
  }))
  const subscribe = (listener: () => void): (() => void) => Effect.runSync(Effect.sync(() => {
    observePathname()
    const changed = () => Effect.runSync(Effect.sync(() => { observePathname(); listener() }))
    window.addEventListener("popstate", changed)
    return () => Effect.runSync(Effect.sync(() => window.removeEventListener("popstate", changed)))
  }))
  return { present, subscribe }
}
const routePresenter = makeRoutePresenter()
export const presentRoute = routePresenter.present
export const subscribeLocation = routePresenter.subscribe

export const subscribeClock = (onTick: (now: number) => void): (() => void) => {
  const tick = Clock.currentTimeMillis.pipe(Effect.flatMap((now) => Effect.sync(() => onTick(now))), Effect.andThen(Effect.sleep("1 second")))
  const interrupt = Effect.runCallback(Effect.forever(tick))
  return () => interrupt()
}

export const openProcessingReport =(details: HTMLDetailsElement, summary: HTMLElement): void => Effect.runSync(Effect.sync(() => {
  details.open = true
  summary.focus({ preventScroll: true })
  summary.scrollIntoView({ block: "start", behavior: "instant" })
}))

const body = yield* Schema.decodeUnknownEffect(RetryRequest)(input, boundaryParseOptions).pipe(Effect.mapError(unpreparedRetry))
const request = yield* HttpClientRequest.post(productRoutes.retry.path.replace(":documentId", id)).pipe(
  HttpClientRequest.setHeader("idempotency-key", key), HttpClientRequest.bodyJson(body), Effect.mapError(transport),
)

if (accepted.documentId !== id || accepted.runId === input.previousRunId) {
  return yield* new DocumentFailure({ kind: "invalid-response", message: unconfirmedRetry })
}

const mismatch = invalid(unreadableOutput)
const readJson = <A>(url: string, schema: Schema.Decoder<A>) => requestJson(HttpClientRequest.get(url), schema, 200)

const sameRevision = (identity: OutputIdentity, canonical: CanonicalDocument, report: ProcessingReport): boolean =>
  canonical.scope.documentId === identity.documentId && canonical.scope.revisionId === identity.revisionId
  && report.scope.documentId === identity.documentId && report.scope.revisionId === identity.revisionId && report.scope.runId === canonical.scope.runId
const acceptedGuideReceipt = (identity: OutputIdentity, canonical: CanonicalDocument, report: ProcessingReport): boolean => {
  const guide = canonical.guide
  if (guide === undefined) return true
  const receipt = report.receipts.find((item) => item.receipt.id === guide.providerAttemptId)?.receipt
  return validGuideSources(guide, canonical.sourceBlocks) && receipt?.stage === "guide" && receipt.scope.documentId === identity.documentId
    && receipt.scope.sourceHash === canonical.sourceHash && receipt.state._tag === "completed" && receipt.state.validation._tag === "accepted"
}

export const readPublishedDocument = Effect.fn("readPublishedDocument")(function* (identity: OutputIdentity) {
  const [canonical, report] = yield* Effect.all([
    readJson(outputUrl(identity, "canonical"), productRoutes.canonical.response),
    readJson(outputUrl(identity, "report"), productRoutes.report.response),
  ], { concurrency: 2 })
  if (!sameRevision(identity, canonical, report)) return yield* mismatch("Output revision mismatch")
  if (!acceptedGuideReceipt(identity, canonical, report)) return yield* mismatch("Reading guide evidence or receipt mismatch")
  return { canonical, report }
})

const response = yield* respond(HttpClientRequest.get(outputUrl(identity, "text")), 200)
if (!response.headers["content-type"]?.toLowerCase().startsWith("text/plain")) return yield* mismatch("Expected normalized text")
return yield* response.text.pipe(Effect.mapError(mismatch))

