  return <dl className="reader-facts"><dt>Blocks updated</dt><dd>{report.changes.changedBlockIds.length}</dd>
    <dt>Headings changed</dt><dd>{report.changes.changedHeadingCount}</dd><dt>Paragraph joins</dt><dd>{report.changes.appliedJoinCount}</dd>
    <dt>Unresolved issues</dt><dd>{report.issues.length}</dd><dt>Verified corrections</dt><dd>{measured(report.verifiedCorrectionCount)}</dd>
    <dt>Ambiguity count</dt><dd>{measured(report.ambiguity)}</dd></dl>
}

type Review = NonNullable<ProcessingReport["museReviews"]>[number]
const keptByFallback: Partial<Record<Review["stage"], string>> = {
  "page-check": "Muse checked this and kept the original text.",
  headings: "Muse checked this and kept the original headings.",
  figures: "Muse checked this and published the figure without an AI description.",
  guide: "Muse checked this and published the document without a reading guide.",
}
const reviewLine = (review: Review, pages: ReadonlyArray<number>): string => {
  const where = pages.length === 0 ? (review.figureId === null ? "" : " a figure") : ` page${pages.length === 1 ? "" : "s"} ${pages.join(", ")}`
  if (review.outcome === "corrected") return `Muse’s check caught a problem${where ? ` on${where}` : ""} and a second review fixed it.`
  return `${keptByFallback[review.stage] ?? "Muse checked this and kept the safe original."}${where ? ` (${where.trim()})` : ""}`
}

function MuseChecks({ report, canonical }: { readonly report: ProcessingReport; readonly canonical: CanonicalDocument | undefined }) {
  const reviews = report.museReviews ?? []
  if (reviews.length === 0) return null
  const pageNumber = (id: string) => canonical?.pages.find((page) => page.id === id)?.pageNumber
  return <section className="reader-muse-checks" aria-labelledby="muse-checks-title"><h3 id="muse-checks-title">What Muse double-checked</h3>
    <ul>{reviews.map((review, index) => <li key={`${review.stage}-${index}`} className={review.outcome}>
      <strong>{stageLabels[review.stage].name}</strong>
      <span>{reviewLine(review, review.pageIds.flatMap((id) => { const number = pageNumber(id); return number === undefined ? [] : [number] }))}</span>
    </li>)}</ul></section>
}

const issueLead = (issue: ProcessingReport["issues"][number], report: ProcessingReport): string | null =>
  issue.code === "provider-failure" && (report.museReviews ?? []).some((review) => review.outcome === "fallback" && review.stage === issue.stage)
    ? keptByFallback[issue.stage as Review["stage"]] ?? null : null

function ReportIssues({ report, onPage }: Pick<ReportProps, "report" | "onPage">) {
  return report.issues.map((issue, index) => {
    const issuePage = issue.locations[0].pageNumber
    const lead = issueLead(issue, report)
    return <div className="reader-issue" key={`${issue.code}-${index}`}><strong>{stageLabels[issue.stage].name} · page {issuePage}</strong>
      {lead !== null && <p className="reader-issue-lead">{lead}</p>}<p>{issue.message}</p>
      <button className="reader-text-link" type="button" onClick={() => onPage(issuePage)}>Compare page {issuePage} →</button></div>
  })
}

function ReportDownloads({ identity }: { readonly identity: OutputIdentity }) {
  return <div className="reader-report-downloads">
    <a className="reader-text-link" href={outputUrl(identity, "report")} download>Download processing report ↓</a>
    <a className="reader-text-link" href={outputUrl(identity, "canonical")} download="document.json">Download document JSON ↓</a></div>
}

const outputSummary = (issueCount: number): string => issueCount === 0 ? "Ready to read and use." : `Ready with ${countLabel(issueCount, "issue")}.`

export function ReportPanel({ report, canonical, identity, onPage, imageSummary, children }: ReportProps) {
  const details = useRef<HTMLDetailsElement>(null)
  const summary = useRef<HTMLElement>(null)
  const issueCount = report.issues.length
  const review = () => { if (details.current !== null && summary.current !== null) openProcessingReport(details.current, summary.current) }
  return <><h2 className="reader-pane-heading">OUTPUT</h2>
    <p className="reader-output-summary">{outputSummary(issueCount)}<span>Normalized text · {imageSummary}</span></p>
    {issueCount > 0 && <button className="reader-text-link reader-review-issues" type="button" onClick={review}>
      Review {issueCount === 1 ? "issue" : "issues"} →</button>}
    {children}
    <MuseChecks report={report} canonical={canonical} />
    <details className="reader-details" ref={details}><summary ref={summary}>Processing report</summary><ReportFacts report={report} />
      <p className="reader-small">Recorded changes are not a count of verified fixes.</p>
      {report.ambiguity._tag === "unavailable" && <p className="reader-small">{report.ambiguity.reason}</p>}
      {report.verifiedCorrectionCount._tag === "unavailable" && <p className="reader-small">{report.verifiedCorrectionCount.reason}</p>}
      <ReportIssues report={report} onPage={onPage} /><ReportDownloads identity={identity} /></details>
    <details className="reader-details"><summary>How this was produced</summary>
      {report.receipts.map(({ receipt, delivery }, index) => <ReceiptStage key={receipt.id} receipt={receipt} delivery={delivery} index={index} />)}
      <p className="reader-small">Settings come from saved attempts. Usage is shown only when reported by the provider.</p></details></>
}

type Delivery = ProcessingReport["receipts"][number]["delivery"]
type Completed = Extract<StageReceipt["state"], { readonly _tag: "completed" }>
type Usage = Completed["usage"] | undefined

const reportedTokens = (usage: Usage, key: "inputTokens" | "outputTokens") => usage?._tag === "reported" ? usage[key] ?? "Unavailable" : "Unavailable"
const reportedCost = (usage: Usage) => usage?._tag === "reported" && usage.costUsd !== null ? `$${usage.costUsd}` : "Unavailable"
const duration = (completed: Completed | null) => completed === null ? "Unavailable" : `${(completed.durationMilliseconds / 1000).toFixed(1)} seconds`
const receiptTarget = (receipt: StageReceipt) => receipt.figureId ?? (receipt.pageIds.length > 0 ? receipt.pageIds.join(", ") : "Document")

function ReceiptStage({ receipt, delivery, index }: { readonly receipt: StageReceipt; readonly delivery: Delivery; readonly index: number }) {
  const config = receipt.configuration
  const model = config._tag === "model" ? config : config.model
  const completed = receipt.state._tag === "completed" ? receipt.state : null
  const usage = completed?.usage
  const prompt = model === undefined ? null : publicPrompt(model.promptName, model.promptVersion)
  return <details className="reader-stage"><summary><span>{String(index + 1).padStart(2, "0")}</span>
    <span>{stageLabels[receipt.stage].name}<small>{model?.model ?? config.provider} · {receiptOutcome(receipt)}</small></span></summary>
    <dl className="reader-run-facts"><dt>Delivery</dt><dd>{delivery === "reused" ? "Reused saved response" : "Performed in this run"}</dd>
      <dt>Provider</dt><dd>{config.provider}</dd>
      {model !== undefined ? <><dt>Model</dt><dd>{model.model}</dd><dt>Reasoning effort</dt><dd>{model.reasoning}</dd>
        <dt>Prompt</dt><dd>{model.promptName} · {model.promptVersion}</dd><dt>Output token ceiling</dt><dd>{model.maxOutputTokens}</dd></>
        : <><dt>Version</dt><dd>{config._tag === "extraction" ? config.version : "Unavailable"}</dd></>}
      <dt>Target</dt><dd>{receiptTarget(receipt)}</dd>
      <dt>Input tokens</dt><dd>{reportedTokens(usage, "inputTokens")}</dd><dt>Output tokens</dt><dd>{reportedTokens(usage, "outputTokens")}</dd>
      <dt>Reported cost</dt><dd>{reportedCost(usage)}</dd><dt>Duration</dt><dd>{duration(completed)}</dd></dl>
    {prompt !== null ? <details className="reader-prompt"><summary>Public prompt template</summary><pre>{prompt}</pre></details>
      : model !== undefined && <p className="reader-small">A public template is unavailable for this prompt version.</p>}
    {receipt.state._tag === "failed" && <p className="reader-small">{receipt.state.failure.message}</p>}
    {completed?.validation._tag === "rejected" && <p className="reader-small">{completed.validation.failure.message}</p>}
    {receipt.state._tag === "unknown-completion" && <p className="reader-small">{receipt.state.reason}</p>}
  </details>
}

type CopyState = "idle" | "pending" | "done"
type Rating = typeof RatingValue.Type
const copyLabels = { idle: "Copy entire normalized text", pending: "Copying…", done: "Copied all text ✓" } as const
const shortCopyLabels = { idle: "Copy all text", pending: "Copying…", done: "Copied ✓" } as const

const guideTitle = (route: GuideRoute, canonical: CanonicalDocument | undefined): string => {
  switch (route.mode) {
    case "walk": return `Step ${Math.min(route.n, canonical?.guide?.steps.length ?? 1)}`
    case "claims": return `Claim ${Math.min(route.n, canonical?.guide?.claims.length ?? 1)}`
    case "overview": return "Overview"
    case "map": return "Document map"
    case "done-walk":
    case "done-claims": return "Guide complete"
    case "choices": return "Your reading goal"
    case "read": return "Read the document"
  }
}

const imageSummary = (canonical: CanonicalDocument | undefined): string => {
  const available = canonical?.figures.filter((figure) => figure.asset._tag === "available").length ?? 0
  return available === 0 ? "No source images" : countLabel(available, "source image")
}

type OutputActionsProps = {
  readonly identity: OutputIdentity
  readonly copyState: CopyState
  readonly rating: Rating | null
  readonly ratingPending: boolean
  readonly message: string | null
  readonly onCopy: () => void
  readonly onRate: (value: Rating) => void
}

function OutputActions({ identity, copyState, rating, ratingPending, message, onCopy, onRate }: OutputActionsProps) {
  return <><div className="reader-downloads"><a className="button primary" href={outputUrl(identity, "zip")} download>↓ Download ZIP</a>
    <a className="reader-text-link" href={outputUrl(identity, "text")} download>Download text only</a>
    <a className="reader-text-link" href={originalUrl(identity.documentId)} download>Download original PDF</a>
    <button className="reader-text-link" type="button" onClick={onCopy} disabled={copyState === "pending"}>{copyLabels[copyState]}</button></div>
    <div className="reader-rating" role="group" aria-label="Rate this output"><span>Was this useful?</span>
      <button className="button" type="button" aria-pressed={rating === "up"} disabled={ratingPending} onClick={() => onRate("up")}>Yes</button>
      <button className="button" type="button" aria-pressed={rating === "down"} disabled={ratingPending} onClick={() => onRate("down")}>
        Needs work</button></div>
    {message !== null && <p className="reader-small reader-action-status" role="status">{message}</p>}</>
}

type EditionProps = {
  readonly documentId: string
  readonly canonical: CanonicalDocument
  readonly identity: OutputIdentity
  readonly paperTitle: string
  readonly titleInPage: boolean
  readonly page: number
  readonly copyState: CopyState
  readonly onCopy: () => void
}

function EditionHead({ documentId, canonical, identity, paperTitle, titleInPage, page, copyState, onCopy }: EditionProps) {
  const go = (route: Parameters<typeof guideLocation>[1]) => navigate(guideLocation(documentId, route, page))
  const guided = canonical.guide !== undefined
  return <header className="reader-edition-head">
    <div className="reader-edition-title"><p className="guide-kicker">Full document</p>{!titleInPage && <h1>{paperTitle}</h1>}</div>
    <div className="reader-edition-tools"><nav className="guide-reader-links" aria-label="Reading options">
      <button type="button" className="reader-text-link" onClick={() => go({ mode: "choices", goal: "read" })}>Choose how to read</button>
      {guided && <button type="button" className="reader-text-link" onClick={() => go({ mode: "overview" })}>Overview</button>}
      {guided && <button type="button" className="reader-text-link" onClick={() => go({ mode: "map", goal: "map" })}>Document map</button>}</nav>
      <div className="live-reader-actions">
        <button className="button" type="button" onClick={onCopy} disabled={copyState === "pending"}>{shortCopyLabels[copyState]}</button>
        <a className="button" href={outputUrl(identity, "zip")} download>Download ZIP</a></div>
    </div>
  </header>
}

type PageReaderProps = {
  readonly canonical: CanonicalDocument
  readonly identity: OutputIdentity
  readonly view: "clean" | "original"
  readonly page: number
  readonly readingPage: RefObject<HTMLElement | null>
  readonly onPage: (number: number) => void
  readonly onView: (view: "clean" | "original") => void
  readonly onPages: () => void
}

function PageText({ canonical, identity, page, onPage, onOriginal }: Pick<PageReaderProps, "canonical" | "identity" | "page" | "onPage"> & {
  readonly onOriginal: () => void
}) {
  const blocks = blocksOnPage(canonical, page)
  const continuations = continuationsOnPage(canonical, page)
  const continuation = (block: Block) => <p className="reader-continuation" key={block.id}>Text from this page continues a paragraph on
    {" "}<button type="button" onClick={() => onPage(blockPage(block))}>page {blockPage(block)} →</button></p>
  return <>
    {continuations.map(continuation)}
    {blocks.map((block) => <ReaderBlock key={block.id} block={block} canonical={canonical} identity={identity} />)}
    {blocks.length === 0 && continuations.length === 0 && <p className="reader-small">No text or figures were extracted from this page.
      {" "}<button type="button" className="reader-text-link" onClick={onOriginal}>View the original page.</button></p>}
  </>
}

function PageReader({ canonical, identity, view, page, readingPage, onPage, onView, onPages }: PageReaderProps) {
  const nextPage = canonical.pages.find((item) => item.pageNumber > page)
  const label = `${view === "clean" ? "Normalized document" : "Original PDF"} page ${page}`
  return <section className="reading-surface" aria-label="Document reader">
    <div className="reading-bar"><div className="reader-view-switch" role="group" aria-label="Reading view">
      <button type="button" aria-pressed={view === "clean"} onClick={() => onView("clean")}>Clean copy</button>
      <button type="button" aria-pressed={view === "original"} onClick={() => onView("original")}>Original</button></div>
      <span>Page {page} of {canonical.pages.length}</span><button className="reader-edge" type="button" onClick={onPages}>Pages</button></div>
    <article className={`paper-content${view === "original" ? " paper-original" : ""}`} ref={readingPage} tabIndex={-1} aria-label={label}>
      {view === "original" ? <OriginalPreview documentId={identity.documentId} page={page} />
        : <PageText canonical={canonical} identity={identity} page={page} onPage={onPage} onOriginal={() => onView("original")} />}
    </article>
    <footer className="reading-footer"><span>END OF PAGE {page}</span>{nextPage === undefined ? <span>End of document</span>
      : <button type="button" className="reader-text-link" onClick={() => onPage(nextPage.pageNumber)}>
        Continue to page {nextPage.pageNumber} →</button>}</footer>
  </section>
}

const trustNote = (fullReader: boolean, canonical: CanonicalDocument): string => {
  if (fullReader) return "AI can change or miss content. Compare anything you rely on with the original."
  if (canonical.guide === undefined) return "The original PDF is available in Downloads & details."
  return "This guide is AI-written. Check the cited passages against the original document."
}

type WorkspaceProps = {
  readonly record: DocumentRecord
  readonly revisionId: OutputRevisionId
  readonly onRefresh: () => void
  readonly onUnauthenticated: () => void
}
type Snapshot = { readonly version: number; readonly data: OutputData | null; readonly error: DocumentReadFailure | null }

export function ReaderWorkspace({ record, revisionId, onRefresh, onUnauthenticated }: WorkspaceProps) {

const [reviewIssues, setReviewIssues] = useState(false)
const [copyState, setCopyState] = useState<CopyState>("idle")
const [rating, setRating] = useState<Rating | null>(null)

const route = guideRouteFromLocation(location)
const view = route.view === "original" ? "original" : "clean"
const lastMode = useRef(route.mode)

const heading = data === null ? undefined : paperHeading(data.canonical)
const paperTitle = heading ?? record.document.originalFilename
const loaded = snapshot.version === version && (data !== null || snapshot.error !== null)
const main = useRoutePresentation(loaded, `${guideTitle(route, data?.canonical)} · ${paperTitle} · AmuseMe`)

  if (data === null) return
  if (lastMode.current !== route.mode && route.mode === "read" && readingPage.current !== null) focusReadingPage(readingPage.current)
  lastMode.current = route.mode
}, [data, route.mode, lastMode])
useEffect(() => {
  const done = pageNavigation === null || completedPageNavigation.current === pageNavigation
  if (done || pageNavigation.page !== page || readingPage.current === null) return

cancelCopy.current = runDocument(copyNormalizedText(identity), () => {
  lock.current.copy = false
  setCopyState("done")
  setMessage("The entire normalized text was copied.")
}, (error) => { lock.current.copy = false; setCopyState("idle"); onFailure(error) })

cancelRating.current = runDocument(saveRating(identity, rating === value ? null : value), (saved) => {
  lock.current.rating = false
  setRatingPending(false)
  setRating(saved)
  setMessage(saved === null ? "Your rating was removed." : "Your rating was saved.")
}, (error) => { lock.current.rating = false; setRatingPending(false); onFailure(error) })

const closeDrawer = () => { setDrawer(null); setReviewIssues(false) }
const reviewAll = () => { setReviewIssues(true); setDrawer("output") }
const retry = () => { setSnapshot({ version: version + 1, data: null, error: null }); setVersion((value) => value + 1) }
const read = (nextView: "clean" | "original") => navigate(guideLocation(record.document.id, { mode: "read", view: nextView }, page))

const fullReader = route.mode === "read"
const titleInPage = view === "clean" && heading !== undefined && page === data?.canonical.pages[0].pageNumber
const issueCount = data?.report.issues.length ?? 0
return <main className={`reader-page live-reader${fullReader ? "" : " goal-reader"}`} id="main-content" ref={main} tabIndex={-1}>
  <div className="reader-toolbar">
    <InternalLink className="back-link" href="/">← Your library</InternalLink>
    {data !== null && <div className="reader-utilities">
      {issueCount > 0 && <button className="reader-text-link reader-issue-link" type="button" aria-haspopup="dialog" onClick={reviewAll}>
        Review {countLabel(issueCount, "issue")}</button>}
      <button className="button reader-download-trigger" type="button" aria-haspopup="dialog" onClick={() => setDrawer("output")}>
        <svg viewBox="0 0 20 20" aria-hidden="true"><path d="M10 2v10m-4-4 4 4 4-4M3 13v4h14v-4" /></svg>Downloads &amp; details</button>
    </div>}
  </div>
  {message !== null && drawer === null && <p className="reader-action-status" role="status">{message}
    {" "}{copyState === "idle" && <a className="reader-text-link" href={outputUrl(identity, "text")} download>Download text instead</a>}</p>}
  {(summary.failed || activeRun(record.latestRun)) && <section className="reader-run-notice" aria-label="Latest processing run">
    {activeRun(record.latestRun) ? <ProcessingProgress record={record} compact /> : <><h2>{summary.title}</h2><p>{summary.description}</p></>}
    <p>Your saved output remains available below.</p>
    <RetryDocumentControl record={record} onRefresh={onRefresh} onUnauthenticated={onUnauthenticated} /></section>}

{snapshot.error !== null && <DocumentReadError error={snapshot.error} onRetry={retry} />}
{data !== null && !fullReader && <GuideWorkspace record={record} canonical={data.canonical} route={route} page={page} />}
{data !== null && fullReader && <EditionHead documentId={record.document.id} canonical={data.canonical} identity={identity} paperTitle={paperTitle}
  titleInPage={titleInPage} page={page} copyState={copyState} onCopy={copy} />}
{data !== null && fullReader && <div className="reader-workspace">
  <aside className="reader-control reader-source" aria-label="Document source">{source}</aside>
  <PageReader canonical={data.canonical} identity={identity} view={view} page={page} readingPage={readingPage}
    onPage={onPage} onView={read} onPages={() => setDrawer("source")} /></div>}
{data !== null && <p className="reader-trust-note">{trustNote(fullReader, data.canonical)}</p>}
{drawer !== null && data !== null && <ReaderDrawer title={drawer === "source" ? "Document source" : "Downloads & details"} side={drawer}
  onClose={closeDrawer} reviewIssues={reviewIssues}>{drawer === "source" ? source : output}</ReaderDrawer>}

