const LegacyExtractedData = Schema.Struct({ conversion: SavedExtraction, receipt: StageReceipt, receipts: Schema.optionalKey(Schema.Never), reviews: Schema.optionalKey(Schema.Never), cropReviews: Schema.optionalKey(Schema.Never), cropReceipts: Schema.optionalKey(Schema.Never) }).pipe(
  Schema.decodeTo(normalizedReceipts, SchemaTransformation.transform({
    decode: ({ conversion, receipt }): typeof normalizedReceipts.Type => ({ conversion, receipts: [receipt] }),
    encode: ({ conversion, receipts }) => ({ conversion, receipt: receipts[0] }),
  })),
)
export const ExtractedData = Schema.Union([CurrentExtractedData, LegacyExtractedData])
export type ExtractedData = typeof ExtractedData.Type
const CorrectedData = Schema.Struct({ corrected: CorrectedText, receipts: Schema.Array(StageReceipt), reviews: Reviews })
const HeadingData = Schema.Struct({ response: HeadingResponse, receipt: Schema.NullOr(StageReceipt), reviews: Reviews })
const DescribedData = Schema.Struct({ figures: Schema.Array(Figure), issues: Schema.Array(Issue), receipts: Schema.Array(StageReceipt), reviews: Reviews })

const imageTokenUpperBound = 131072
const figureImageAllowanceBytes = 100 * 1024 * 1024

const isPageReceipt = (receipt: StageReceipt, page: Page | undefined, configuration: ReturnType<typeof stageConfiguration>) =>
  receipt.stage === "extraction" && Equal.equals(receipt.configuration, configuration) && receipt.pageIds.length === 1 && receipt.pageIds[0] === page?.id
const belongsToRun = (receipt: StageReceipt, claim: DispatchClaim) =>
  receipt.ownerId === claim.document.ownerId && receipt.scope.documentId === claim.document.id && receipt.scope.sourceHash === claim.document.sourceHash
  && receipt.pipelineVersion === claim.run.pipelineVersion && receipt.schemaVersion === claim.run.schemaVersion
const isAccepted = (receipt: StageReceipt) => receipt.state._tag === "completed" && receipt.state.validation._tag === "accepted"
const receiptsCoverPagesInOrder = (claim: DispatchClaim, extraction: Extraction, receipts: ReadonlyArray<StageReceipt>) => {
  const configuration = stageConfiguration(claim.run.configuration, "extraction")
  return new Set(receipts.map((receipt) => receipt.id)).size === receipts.length && receipts.length === extraction.pages.length
    && receipts.every((receipt, index) => isPageReceipt(receipt, extraction.pages[index], configuration) && belongsToRun(receipt, claim) && isAccepted(receipt))
}
const sameArtifact = (stored: PrivateArtifact, expected: PrivateArtifact) => stored.hash === expected.hash && stored.byteCount === expected.byteCount
const deliveryFor = (claim: DispatchClaim, receipt: StageReceipt) => receipt.scope.runId === claim.run.id ? "performed" as const : "reused" as const
const missingGuideReservation = () => executionFailure("processing-unavailable", "The reading guide requires an explicit provider reservation")
const reviewedFigureBoxes = (page: Page, extracted: ValidatedPageExtraction, boxes: ReadonlyMap<number, PixelBox>): Result.Result<ValidatedPageExtraction, ExecutionFailure> => {
  if (boxes.size === 0) return Result.succeed(extracted)
  const figures = extracted.figures.map((figure) => {
    const box = boxes.get(figure.blockIndex)
    return box === undefined ? figure : { ...figure, box: { x: box.x, y: box.y, width: box.width, height: box.height } }
  })
  return Result.mapError(pageExtractionProblems(page, { ...extracted, figures }), () => executionFailure("invalid-provider-response", "A reviewed figure crop no longer fits its page"))
}
const isUnavailableFigureFailure = (failure: ExecutionFailure | StorageFailure) =>
  failure._tag === "ExecutionFailure" && failure.code !== "provider-unknown-completion" && failure.code !== "conflict"

interface MetaCall {
  readonly stage: MetaStage
  readonly task?: ProviderTask
  readonly headroomMicrousd?: number
  readonly request: MetaRequest
  readonly limits: StageRequestLimits
  readonly validate: (value: Schema.Json) => Result.Result<unknown, ExecutionFailure>
  readonly pageIds: ReadonlyArray<PageId>
  readonly figureId: FigureId | null
  readonly inputHashes: ReadonlyArray<ArtifactHash>
  readonly savedInput?: unknown
}
type Checked<A> = Result.Result<A, ReadonlyArray<string>>
interface ReviewedUnit<A, F> extends Omit<MetaCall, "validate"> {
  readonly check: (value: Schema.Json) => Checked<A>
  readonly headroomMicrousd: number
  readonly fallback: (rejected: Schema.Json | null) => { readonly value: F; readonly summary: string } | null
  readonly unavailable?: (failure: ExecutionFailure, dispatched: boolean) => boolean
}
type Reviewed<A, F> =
  | { readonly _tag: "accepted"; readonly value: A; readonly receipt: StageReceipt; readonly review: MuseReview | null }
  | { readonly _tag: "fallback"; readonly value: F; readonly attemptId: ProviderAttemptId | null; readonly review: MuseReview | null; readonly reason: string }
const problemLimit = 20
const conciseProblems = (problems: ReadonlyArray<string>): readonly [string, ...Array<string>] => {
  const listed = problems.slice(0, problemLimit).map((problem) => problem.length > 400 ? `${problem.slice(0, 397)}...` : problem)
  const more = problems.length > problemLimit ? [`${problems.length - problemLimit} more problems`] : []
  const [first, ...rest] = [...listed, ...more]
  return first === undefined ? ["The answer did not pass validation"] : [first, ...rest]
}
const rejectionMessage = (problems: ReadonlyArray<string>) => `Muse review needed: ${conciseProblems(problems).slice(0, 3).join("; ")}`
const reviewUnavailable = (failure: GuardError | ExecutionFailure): failure is ExecutionFailure =>
  failure._tag === "ExecutionFailure" && (failure.code === "limit-exceeded" || failure.code === "provider-failed")
const preflightUnavailable = (failure: GuardError | ExecutionFailure): failure is ExecutionFailure =>
  failure._tag === "ExecutionFailure" && failure.code !== "processing-unavailable"
interface CroppedFigure {
  readonly box: PixelBox
  readonly asset: ImageArtifact
  readonly bytes: Uint8Array
}
const cropProblemText = (problem: string) => problem.length > 400 ? `${problem.slice(0, 397)}...` : problem
const cropWarning = (outcome: "unconfirmed" | "not-reviewed", reason: string) => outcome === "not-reviewed"
  ? `Muse could not check this figure's crop (${reason}); the extractor's proposed region is published unreviewed and may cut off part of the figure or include nearby text.`
  : `Muse did not confirm this figure's crop after ${figureCropRounds} review rounds; the last valid region is published and may cut off part of the figure or include nearby text.`
const pageLocations = (extraction: Extraction, pageIds: ReadonlyArray<PageId>) =>
  extraction.pages.filter((page) => pageIds.includes(page.id)).map((page) => ({ _tag: "page" as const, pageId: page.id, pageNumber: page.pageNumber }))
const fallbackIssue = (review: MuseReview, extraction: Extraction): Array<Issue> => {
  const [first, ...rest] = pageLocations(extraction, review.pageIds)
  if (review.outcome !== "fallback" || review.stage === "figures" || first === undefined) return []
  const message = `Muse review could not correct the ${review.stage} answer. ${review.fallback ?? "A safe fallback was used."}`
  return [{ code: "provider-failure", message, stage: review.stage, locations: [first, ...rest], blockIds: [], figureId: null }]
}
const specFor = (claim: DispatchClaim, stage: MetaStage): MetaStageSpec => stage === "page-check" ? pageCheckSpecFor(claim.run.configuration.pageCheck.promptVersion) : stageSpecs[stage]
interface MetaPreflight {
  readonly inputTokens: number
  readonly framingReserveTokens: number
}

static readonly layer = (meta: ReturnType<typeof makeMetaAgentBoundary>, options?: PipelineOptions) =>
  Layer.effect(NormalizationStages, Effect.gen(function* () {
  if (options === undefined) {
    const message = "Document processing is not configured"
    const failure = { code: "processing-unavailable", message, retryable: false, stage: null, pageId: null, figureId: null } as const
    return NormalizationStages.of({ execute: () => Effect.fail(new WorkflowStageFailure({ failure })) })
  }

const dispatch = (claim: DispatchClaim, prepared: Effect.Success<ReturnType<typeof prepareMetaCall>>) =>
  guard.execute(claim, prepared.attempt).pipe(Effect.provideService(ProviderAdapter, prepared.adapter))
const guardedMetaCall = (claim: DispatchClaim, call: MetaCall) => measure(call.request).pipe(
  Effect.flatMap((preflight) => prepareMetaCall(claim, call, preflight)),
  Effect.flatMap((prepared) => dispatch(claim, prepared)),
)
const attemptCall = (claim: DispatchClaim, call: MetaCall, retry: AttemptInput["retry"]) => measure(call.request).pipe(
  Effect.flatMap((preflight) => prepareMetaCall(claim, call, preflight, retry)),
  Effect.flatMap((prepared) => dispatch(claim, prepared).pipe(Effect.result, Effect.map((result) => ({ attempt: prepared.attempt, result })))),
)

const reviewedMetaCall = Effect.fnUntraced(function* <A, F>(claim: DispatchClaim, unit: ReviewedUnit<A, F>) {
  const validate = (value: Schema.Json) => Result.mapError(unit.check(value), (problems) => invalidStage(rejectionMessage(problems)))
  const attemptIds: Array<ProviderAttemptId> = []
  let problems: ReadonlyArray<string> | null = null
  let lastRejected: Schema.Json | null = null
  const record = (outcome: MuseReview["outcome"], fallback: string | null): MuseReview | null => {
    const [first, ...rest] = attemptIds
    return problems === null || first === undefined ? null : {
      stage: unit.stage, agent: museReviewAgentId(unit.stage), pageIds: unit.pageIds, figureId: unit.figureId,
      problems: conciseProblems(problems), rounds: attemptIds.length - 1, attemptIds: [first, ...rest], outcome, fallback,
    }
  }
  const fallBack = (reason: string): Effect.Effect<Reviewed<A, F>, ExecutionFailure> => {
    const safe = unit.fallback(lastRejected)
    if (safe === null) return Effect.fail(invalidStage(reason))
    return Effect.succeed({ _tag: "fallback", value: safe.value, attemptId: attemptIds.at(-1) ?? null, review: record("fallback", safe.summary), reason: safe.summary })
  }
  let request = unit.request
  let retry: AttemptInput["retry"] = { _tag: "none" }
  for (let round = 0; ; round += 1) {
    const call = { ...unit, request, validate }
    const prepared = yield* attemptCall(claim, call, retry).pipe(Effect.result)
    if (prepared._tag === "Failure") {
      const failure = prepared.failure
      if (round === 0 && failure._tag === "ExecutionFailure" && unit.unavailable?.(failure, false) === true) return yield* fallBack(failure.message)
      if (round > 0 && preflightUnavailable(failure)) return yield* fallBack(failure.message)
      return yield* failure
    }
    const { attempt, result } = prepared.success
    let rejected: GuardedResponse
    let current: ReadonlyArray<string>
    let decoded: Schema.Json | null
    if (result._tag === "Success") {
      const value = yield* decodeMetaOutput(result.success.response)
      const checked = unit.check(value)
      if (Result.isSuccess(checked)) {
        if (round > 0) attemptIds.push(result.success.receipt.id)
        return { _tag: "accepted", value: checked.success, receipt: result.success.receipt, review: round === 0 ? null : record("corrected", null) } satisfies Reviewed<A, F>

      rejected = result.success; current = checked.failure; decoded = value
    } else {
      const failure = result.failure
      if (failure._tag !== "ExecutionFailure" || failure.code !== "invalid-provider-response") {
        if (round === 0 && failure._tag === "ExecutionFailure" && unit.unavailable?.(failure, true) === true) return yield* fallBack(failure.message)
        if (round > 0 && reviewUnavailable(failure)) return yield* fallBack(failure.message)
        return yield* failure
      }
      const saved = yield* guard.rejected(claim, attempt)
      if (saved === null) return yield* failure
      const value = yield* decodeMetaOutput(saved.response).pipe(Effect.option)
      const checked = value._tag === "Some" ? unit.check(value.value) : null
      rejected = saved; decoded = value._tag === "Some" ? value.value : null
      current = checked !== null && Result.isFailure(checked) ? checked.failure : [failure.message]
    }
    attemptIds.push(rejected.receipt.id)
    problems ??= current
    if (decoded !== null) lastRejected = decoded
    const state = rejected.receipt.state
    const text = metaAssistantText(rejected.response)
    if (round >= museReviewRounds || text === null || state._tag !== "completed") return yield* fallBack(rejectionMessage(current))
    const review = boundRequest(makeMuseReviewRequest(unit.stage, specFor(claim, unit.stage), unit.request, {
      round: round + 1, rejectedAnswer: text, rejectedAnswerSha256: state.responseHash, problems: conciseProblems(current),
    }), unit.limits)
    if (Result.isFailure(review)) return yield* fallBack(review.failure.message)
    request = review.success
    retry = { _tag: "review", previousAttemptId: rejected.receipt.id, round: round === 0 ? 1 : 2, headroomMicrousd: Math.max(0, unit.headroomMicrousd) }
  }
})

const renderPages = Effect.fnUntraced(function* (claim: DispatchClaim) {
  const original = yield* documents.original(claim.document.ownerId, claim.document.id)
  const directory = yield* fs.makeTempDirectoryScoped({ directory: options.temporaryDirectory, prefix: "render-" })
  yield* fs.chmod(directory, 0o700)
  const source = path.join(directory, "source.pdf")
  yield* fs.writeFile(source, original.bytes, { flag: "wx", mode: 0o600 })
  const { byteCount, sourceHash, pageCount } = claim.document
  const pages = yield* renderer.render({ privatePath: source, byteCount, sourceHash, pageCount, outputDirectory: directory })
  for (const page of pages) {
    const bytes = yield* fs.readFile(path.join(directory, page.image.path))
    const stored = yield* artifacts.put(claim.document.ownerId, claim.document.id, bytes)
    if (!sameArtifact(stored, page.image)) return yield* executionFailure("invalid-provider-response", "Rendered page integrity check failed")
  }
  return pages
}, Effect.scoped)
const cropFigure = Effect.fnUntraced(function* (
  claim: DispatchClaim, page: Page, pageImage: Uint8Array, proposal: PageExtractionResponse["figures"][number], box: PixelBox, corrected = false,
) {
  const directory = yield* fs.makeTempDirectoryScoped({ directory: options.temporaryDirectory, prefix: "figure-" })
  yield* fs.chmod(directory, 0o700)
  const privatePath = path.join(directory, "page.png")
  const outputPath = path.join(directory, "figure.png")
  yield* fs.writeFile(privatePath, pageImage, { flag: "wx", mode: 0o600 })
  const croppedResult = yield* renderer.crop({ privatePath, outputPath, page, box }).pipe(Effect.result)
  if (croppedResult._tag === "Failure") {
    if ((croppedResult.failure.code === "invalid-input" && !corrected) || croppedResult.failure.code === "storage-failed") return yield* croppedResult.failure
    return null
  }
  const cropped = croppedResult.success
  const bytes = yield* fs.readFile(outputPath)
  const stored = yield* artifacts.put(claim.document.ownerId, claim.document.id, bytes)
  if (!sameArtifact(stored, cropped)) return yield* executionFailure("invalid-provider-response", "Figure crop integrity check failed")
  const asset: ImageArtifact = { path: `images/page-${page.pageNumber}-figure-${proposal.blockIndex + 1}.png`, mediaType: "image/png", ...stored }
  return { box, asset, bytes } satisfies CroppedFigure
}, Effect.scoped)

const reviewFigureCrop = Effect.fnUntraced(function* (
  claim: DispatchClaim, page: Page, pageImage: Uint8Array, extracted: PageExtractionResponse, proposal: PageExtractionResponse["figures"][number],
  initial: CroppedFigure, headroomMicrousd: number,
) {
  const figureId = pageFigureId(page.pageNumber, proposal.blockIndex)
  const label = extracted.blocks[proposal.blockIndex]?.content ?? "[Figure]"
  const caption = proposal.captionBlockIndices.map((index) => extracted.blocks[index]?.content ?? "").join("\n\n")
  const figureLimits = limits(claim, "figures")
  const receipts: Array<StageReceipt> = []
  const problems: Array<string> = []
  let current = initial
  let changed = false
  let previous: { readonly answer: unknown; readonly problems: ReadonlyArray<string> } | null = null
  const finish = (outcome: FigureCropReview["outcome"], reason: string | null) => ({
    crop: current,
    receipts,
    review: {
      figureId, pageId: page.id, agent: figureCropReviewAgentId, outcome, rounds: receipts.length, attemptIds: receipts.map((receipt) => receipt.id),
      proposedBox: initial.box, finalBox: current.box, problems: problems.slice(0, problemLimit).map(cropProblemText),
      warning: outcome === "unconfirmed" || outcome === "not-reviewed" ? cropWarning(outcome, reason ?? "review unavailable") : null,
    } satisfies FigureCropReview,
  })
  const unreviewed = (reason: string) => finish(receipts.length === 0 ? "not-reviewed" : "unconfirmed", reason)
  const unavailable = (failure: GuardError | ExecutionFailure) => reviewUnavailable(failure) ? unreviewed(failure.message) : null
  for (let round = 1; round <= figureCropRounds; round += 1) {
    const box = current.box
    const request = buildFigureCropRequest({ page, pageImage, crop: { bytes: current.bytes, artifact: current.asset }, box, label, caption, round, previous }, figureLimits)
    if (Result.isFailure(request)) return unreviewed(request.failure.message)
    const call: MetaCall = {
      stage: "figures", task: "figure-crop", request: request.success, limits: figureLimits, pageIds: [page.id], figureId,
      inputHashes: [page.image.hash, current.asset.hash], ...(round === 1 ? { headroomMicrousd } : {}),
      validate: (value) => Result.mapError(figureCropProblems(page, initial.box, box, value), (found) => invalidStage(`Figure crop review rejected: ${found.slice(0, 3).join("; ")}`)),
    }
    const previousAttemptId = receipts.at(-1)?.id
    const retry: AttemptInput["retry"] = previousAttemptId === undefined ? { _tag: "none" } : { _tag: "review", previousAttemptId, round: 1, headroomMicrousd: Math.max(0, headroomMicrousd) }
    const prepared = yield* attemptCall(claim, call, retry).pipe(Effect.result)
    if (prepared._tag === "Failure") return preflightUnavailable(prepared.failure) ? unreviewed(prepared.failure.message) : yield* prepared.failure
    const { attempt, result } = prepared.success
    let answer: Schema.Json | null
    let verdict: ReturnType<typeof figureCropProblems>
    if (result._tag === "Success") {
      answer = yield* decodeMetaOutput(result.success.response)
      verdict = figureCropProblems(page, initial.box, box, answer)
      receipts.push(result.success.receipt)
    } else {
      const failure = result.failure
      if (failure._tag !== "ExecutionFailure" || failure.code !== "invalid-provider-response") return unavailable(failure) ?? (yield* failure)
      const saved = yield* guard.rejected(claim, attempt)
      if (saved === null) return yield* failure
      const decoded = yield* decodeMetaOutput(saved.response).pipe(Effect.option)
      answer = decoded._tag === "Some" ? decoded.value : null
      verdict = answer === null ? Result.fail([failure.message]) : figureCropProblems(page, initial.box, box, answer)
      receipts.push(saved.receipt)
    }
    if (Result.isFailure(verdict)) {
      problems.push(...verdict.failure)
      previous = { answer, problems: verdict.failure }
      continue
    }
    if (verdict.success._tag === "confirmed") return finish(changed ? "corrected" : "confirmed", null)
    const recropped = yield* cropFigure(claim, page, pageImage, proposal, verdict.success.box, true)
    if (recropped === null) {
      const problem = "The corrected box could not be cropped from the rendered page"
      problems.push(problem)
      previous = { answer, problems: [problem] }
      continue
    }
    current = recropped
    changed = true
    previous = { answer, problems: [] }
  }
  return finish("unconfirmed", null)
})

const extract = Effect.fnUntraced(function* (claim: DispatchClaim, input: Checkpoint) {
  const stage = "extraction"
  const reserved = options.policy.maximumCostMicrousd
  const guideReservation = claim.run.configuration.guide === undefined ? 0 : reserved.guide
  if (guideReservation === undefined) return yield* missingGuideReservation()
  const mandatoryReservation = claim.document.pageCount * (reserved.extraction + reserved["page-check"]) + reserved.headings + guideReservation
  if (!Number.isSafeInteger(mandatoryReservation) || mandatoryReservation > Math.floor(claim.run.configuration.spendingCapUsd * 1_000_000)) {
    return yield* executionFailure("limit-exceeded", "This document exceeds its reserved processing allowance before figure descriptions")
  }
  yield* progress(claim, stage, 0, claim.document.pageCount)
  const rendered = yield* renderPages(claim)
  const model = claim.run.configuration.extractionModel
  if (model === undefined) return yield* executionFailure("processing-unavailable", "The Meta extraction model is not configured")
  const extractionLimits = { maxOutputTokens: model.maxOutputTokens, maxRequestBytes: options.policy.maxRequestBytes, imageTokenUpperBound }
  const receipts: Array<StageReceipt> = []
  const reviews: Array<MuseReview> = []
  const cropReviews: Array<FigureCropReview> = []
  const cropReceipts: Array<StageReceipt> = []
  const pages: Array<Extraction> = []
  const issues: Array<Issue> = []
  let totalFigureBytes = 0
  const legacy = model.promptVersion === "1"
  if (legacy && (rendered.length !== 1 || rendered[0]?.physicalRotation !== 0)) {
    return yield* new PdfRenderError({ code: "unsupported-pdf", message: "The historical extraction trial requires one unrotated page" })
  }
  if (!legacy && model.promptVersion !== pageExtractionPromptVersion) {
    return yield* executionFailure("processing-unavailable", "The extraction prompt version is not supported")
  }
  for (const renderedPage of rendered) {
    const page = extractionPage(renderedPage)
    const imageBytes = yield* readPrivate(claim, page.image)
    const request = yield* Effect.fromResult(legacy
      ? buildExtractionRequest(page, imageBytes, extractionLimits)
      : buildPageExtractionRequest(page, claim.document.pageCount, imageBytes, extractionLimits))
    if (legacy) {
      const response = yield* guardedMetaCall(claim, {
        stage, request, limits: extractionLimits, pageIds: [page.id], figureId: null, inputHashes: [page.image.hash],
        validate: (value) => convertSparkExtraction(claim.document, claim.run.id, page, value),
      })

  pages.push(conversion.extraction); issues.push(...conversion.issues)
  receipts.push(response.receipt)
} else {
  const response = yield* reviewedMetaCall(claim, {
    stage, request, limits: extractionLimits, pageIds: [page.id], figureId: null, inputHashes: [page.image.hash],
    headroomMicrousd: mandatoryReservation - (receipts.length + 1) * reserved.extraction,
    check: (value) => pageExtractionProblems(page, value), fallback: () => null,
  })
  if (response._tag !== "accepted") return yield* executionFailure("invalid-provider-response", response.reason)
  if (response.review !== null) reviews.push(response.review)
  receipts.push(response.receipt)
  const extractedPage = response.value
  const images = new Map<number, ImageArtifact>()
  const boxes = new Map<number, PixelBox>()
  const pageCrops: Array<FigureCropReview> = []
  const cropHeadroom = mandatoryReservation - receipts.length * reserved.extraction
  for (const proposal of extractedPage.figures) {
    if (proposal.box === null) continue
    const initial = yield* cropFigure(claim, page, imageBytes, proposal, cropBox(proposal.box))
    if (initial === null) continue
    const reviewed = yield* reviewFigureCrop(claim, page, imageBytes, extractedPage, proposal, initial, cropHeadroom)
    totalFigureBytes += reviewed.crop.asset.byteCount
    if (totalFigureBytes > figureImageAllowanceBytes) {
      return yield* executionFailure("limit-exceeded", "Figure images exceed the document image allowance")
    }
    images.set(proposal.blockIndex, reviewed.crop.asset)
    boxes.set(proposal.blockIndex, reviewed.crop.box)
    pageCrops.push(reviewed.review)
    cropReceipts.push(...reviewed.receipts)
  }
  const reviewedPage = yield* Effect.fromResult(reviewedFigureBoxes(page, extractedPage, boxes))
  const conversion = convertPageExtraction(claim.document, claim.run.id, page, reviewedPage, images)
  pages.push(conversion.extraction); issues.push(...conversion.issues)
  cropReviews.push(...pageCrops)
  for (const crop of pageCrops) {
    const figure = conversion.extraction.figures.find((item) => item.id === crop.figureId)
    if (figure !== undefined && crop.warning !== null) {
      issues.push({ code: "figure-crop-unconfirmed", message: crop.warning, stage: "extraction", locations: figure.locations, blockIds: figure.sourceBlockIds, figureId: figure.id })
    }
  }

  const sourceBlocks = pages.flatMap((page) => page.sourceBlocks).map((block, readingOrder) => ({ ...block, readingOrder }))
  const extraction = yield* Schema.decodeUnknownEffect(Extraction)({
    schemaVersion: "1", scope: { documentId: claim.document.id, runId: claim.run.id, sourceHash: claim.document.sourceHash },
    pages: pages.flatMap((page) => page.pages), sourceBlocks,
    pageFurniture: pages.flatMap((page) => page.pageFurniture ?? []), figures: pages.flatMap((page) => page.figures),
  })
  if (validateExtraction(claim.document, extraction).length !== 0) {
    return yield* executionFailure("invalid-provider-response", "Extracted pages do not cover the admitted document")
  }
  return { documentId: input.documentId, runId: input.runId, extraction: yield* save(claim, { conversion: { extraction, issues }, receipts, ...(reviews.length === 0 ? {} : { reviews }), ...(cropReviews.length === 0 ? {} : { cropReviews }), ...(cropReceipts.length === 0 ? {} : { cropReceipts }) }) }
})

const loadExtracted = Effect.fnUntraced(function* (claim: DispatchClaim, input: Checkpoint) {

if (claim.run.configuration.extractionModel?.promptVersion === pageExtractionPromptVersion) {
  const valid = receiptsCoverPagesInOrder(claim, extraction, data.receipts) && extraction.scope.runId === claim.run.id
    && validateExtraction(claim.document, extraction).length === 0
  if (!valid) return yield* executionFailure("invalid-provider-response", "Saved extraction receipts must cover every page in order")

  return { extracted, data, extraction }
})
const loadCorrected = Effect.fnUntraced(function* (claim: DispatchClaim, input: Checkpoint) {
  const previous = yield* loadExtracted(claim, input)
  const corrected = yield* Schema.decodeUnknownEffect(Corrected)(input)
  return { ...previous, corrected, correction: yield* read(claim, corrected.correction, CorrectedData) }
})
const loadHierarchy = Effect.fnUntraced(function* (claim: DispatchClaim, input: Checkpoint) {
  const previous = yield* loadCorrected(claim, input)

  yield* Effect.fromResult(applyHeadingDecisions(previous.extraction, previous.correction.corrected, headings.response))
  return { ...previous, hierarchy, headings }
})
const loadDescribed = Effect.fnUntraced(function* (claim: DispatchClaim, input: Checkpoint) {
  const previous = yield* loadHierarchy(claim, input)
  const described = yield* Schema.decodeUnknownEffect(Described)(input)
  return { ...previous, described, descriptions: yield* read(claim, described.descriptions, DescribedData) }
})
const loadAssembled = Effect.fnUntraced(function* (claim: DispatchClaim, input: Checkpoint) {
  const previous = yield* loadDescribed(claim, input)
  const assembled = yield* Schema.decodeUnknownEffect(Assembled)(input)
  return { ...previous, assembled, publication: yield* read(claim, assembled.publication, AssembledDocument) }
})

const checkPages = Effect.fnUntraced(function* (claim: DispatchClaim, input: Checkpoint) {
  const stage = "page-check"
  const { extracted, extraction } = yield* loadExtracted(claim, input)
  const checked: Array<CheckedPage> = []
  const receipts: Array<StageReceipt> = []
  const reviews: Array<MuseReview> = []
  yield* progress(claim, stage, 0, extraction.pages.length)
  for (const page of extraction.pages) {
    const bytes = yield* readPrivate(claim, page.image)
    const prepared = yield* Effect.fromResult(buildPageCheckRequest(extraction, page.id, bytes, limits(claim, "pageCheck"), specFor(claim, stage)))
    const earlier = checked.map((entry) => entry.result)
    const remaining = extraction.pages.length - checked.length - 1
    const response = yield* reviewedMetaCall(claim, {
      stage, request: prepared.request, limits: limits(claim, "pageCheck"), pageIds: [page.id], figureId: null, inputHashes: [page.image.hash],
      headroomMicrousd: remaining * reservation("page-check") + reservation("headings") + guideAllowance(claim),
      check: (value) => pageResponseProblems(extraction, page.id, value, earlier),
      fallback: (rejected) => {
        const { result, dropped } = salvagePageResponse(extraction, page.id, rejected, earlier)
        const kept = result.fixes.length + result.joins.length
        return { value: result, summary: `Kept ${kept} proposed change${kept === 1 ? "" : "s"} that passed every check and dropped ${dropped}; all other text on this page stays as extracted.` }
      },
    })
    const providerAttemptId = response._tag === "accepted" ? response.receipt.id : response.attemptId
    if (providerAttemptId === null) return yield* executionFailure("invalid-provider-response", "A page check fallback requires its reviewed attempt")
    checked.push({ scope: extraction.scope, pageId: page.id, previousContextIds: prepared.previousContextIds, result: response.value, providerAttemptId })
    if (response._tag === "accepted") receipts.push(response.receipt)
    if (response.review !== null) reviews.push(response.review)
    yield* progress(claim, stage, checked.length, extraction.pages.length)
  }
  const corrected = yield* Effect.fromResult(applyPageChecks(extraction, checked))
  return { ...extracted, correction: yield* save(claim, { corrected, receipts, ...(reviews.length === 0 ? {} : { reviews }) }) }
})

const classifyHeadings = Effect.fnUntraced(function* (claim: DispatchClaim, input: Checkpoint) {
  const stage = "headings"
  const { corrected, correction, extraction } = yield* loadCorrected(claim, input)
  yield* progress(claim, stage, 0, 1)
  const request = yield* Effect.fromResult(buildHeadingRequest(extraction, correction.corrected, limits(claim, "headings")))
  const response = yield* reviewedMetaCall(claim, {
    stage, request, limits: limits(claim, "headings"), pageIds: extraction.pages.map((page) => page.id), figureId: null, inputHashes: [],
    headroomMicrousd: guideAllowance(claim),
    check: (value) => headingResponseProblems(correction.corrected, value),
    fallback: () => {
      const decisions = extractorHeadingDecisions(correction.corrected)
      return Result.isSuccess(validateHeadingResponse(extraction, correction.corrected, decisions))
        ? { value: decisions, summary: "Kept the extractor's own heading classification, with at most one level-1 title." } : null
    },
  })
  yield* progress(claim, stage, 1, 1)
  const receipt = response._tag === "accepted" ? response.receipt : null
  return { ...corrected, hierarchy: yield* save(claim, { response: response.value, receipt, ...(response.review === null ? {} : { reviews: [response.review] }) }) }
})

const describeFigures = Effect.fnUntraced(function* (claim: DispatchClaim, input: Checkpoint) {
  const stage = "figures"
  const { hierarchy, correction, extraction } = yield* loadHierarchy(claim, input)
  const figures: Array<Figure> = []
  const issues: Array<Issue> = []
  const receipts: Array<StageReceipt> = []
  const reviews: Array<MuseReview> = []
  const markUnavailable = (figure: Figure, reason: string) => {
    const unavailable = unavailableFigure(figure, reason)
    figures.push(unavailable.figure); issues.push(unavailable.issue)
  }
  yield* progress(claim, stage, 0, extraction.figures.length)
  for (const figure of extraction.figures) {
    const bytes = figure.asset._tag === "available" ? yield* readPrivate(claim, figure.asset.artifact) : null
    const preparation = yield* Effect.fromResult(buildFigureRequest(extraction, correction.corrected, figure, bytes, limits(claim, "figures")))
    if (preparation._tag === "unavailable") {
      figures.push(preparation.figure); issues.push(preparation.issue)

const response = yield* reviewedMetaCall(claim, {
  stage, request: preparation.request, limits: limits(claim, "figures"),
  pageIds: figure.locations.map((location) => location.pageId), figureId: figure.id,
  inputHashes: figure.asset._tag === "available" ? [figure.asset.artifact.hash] : [],
  headroomMicrousd: guideAllowance(claim), check: figureResponseProblems,
  fallback: () => ({ value: null, summary: "Published the figure without an AI description." }),
  unavailable: (failure, dispatched) => dispatched ? isUnavailableFigureFailure(failure) : failure.code === "provider-failed",
})
if (response.review !== null) reviews.push(response.review)
if (response._tag === "fallback") markUnavailable(figure, response.reason)
else {
  figures.push(yield* Effect.fromResult(applyFigureDescription(figure, response.value, response.receipt.id)))
  receipts.push(response.receipt)
}
yield* progress(claim, stage, figures.length, extraction.figures.length)

  return { ...hierarchy, descriptions: yield* save(claim, { figures, issues, receipts, ...(reviews.length === 0 ? {} : { reviews }) }) }
})

const assemble = Effect.fnUntraced(function* (claim: DispatchClaim, input: Checkpoint) {
  const stage = "assembly"
  const { described, descriptions, headings, correction, extraction, data } = yield* loadDescribed(claim, input)
  yield* progress(claim, stage, 0, 1)
  const rows = yield* database.query("assembly-receipts", () => database.db.selectFrom("provider_attempts").select("receipt_json")
    .where("owner_id", "=", claim.document.ownerId).where("document_id", "=", claim.document.id).where("run_id", "=", claim.run.id)
    .orderBy("created_at", "asc").execute())
  const receipts = new Map([...data.receipts, ...data.cropReceipts ?? [], ...correction.receipts, ...headings.receipt === null ? [] : [headings.receipt], ...descriptions.receipts].map((receipt) => [receipt.id, receipt]))
  const museReviews = [...data.reviews ?? [], ...correction.reviews ?? [], ...headings.reviews ?? [], ...descriptions.reviews ?? []]
  for (const row of rows) {
    const receipt = yield* Schema.decodeUnknownEffect(Schema.fromJsonString(StageReceipt))(row.receipt_json)
    receipts.set(receipt.id, receipt)
  }
  const receiptUses: Array<ReceiptUse> = [...receipts.values()].map((receipt) => ({ receipt, delivery: deliveryFor(claim, receipt) }))
  const assembled = yield* Effect.fromResult(assembleDocument({
    document: claim.document, run: claim.run, revisionId: OutputRevisionId.make(claim.run.id), extraction, corrected: correction.corrected,
    headings: yield* Effect.fromResult(applyHeadingDecisions(extraction, correction.corrected, headings.response)),
    figures: descriptions.figures, issues: [...data.conversion.issues, ...descriptions.issues, ...museReviews.flatMap((review) => fallbackIssue(review, extraction))], receiptUses,
    ...(museReviews.length === 0 ? {} : { museReviews }),
    ...(data.cropReviews === undefined || data.cropReviews.length === 0 ? {} : { figureCrops: data.cropReviews }),
  }))
  yield* progress(claim, stage, 1, 1)
  return { ...described, publication: yield* save(claim, assembled) }
})

const writeGuide = Effect.fnUntraced(function* (claim: DispatchClaim, input: Checkpoint) {
  const stage = "guide"
  const { assembled, publication } = yield* loadAssembled(claim, input)
  const configuration = claim.run.configuration.guide
  if (configuration === undefined) return assembled
  if (options.policy.maximumCostMicrousd.guide === undefined) return yield* missingGuideReservation()
  yield* progress(claim, stage, 0, 1)
  const guideLimits = { maxOutputTokens: configuration.maxOutputTokens, maxRequestBytes: options.policy.maxRequestBytes, imageTokenUpperBound: 0 }
  const request = yield* Effect.fromResult(buildGuideRequest(publication.canonical, guideLimits))
  const pageIds = publication.canonical.pages.map((page) => page.id)
  const response = yield* reviewedMetaCall(claim, {
    stage, request, limits: guideLimits, pageIds, figureId: null, inputHashes: [], savedInput: guideInput(publication.canonical),
    headroomMicrousd: 0, check: (value) => guideResponseProblems(publication.canonical, value),
    fallback: () => ({ value: null, summary: "Published the document without a reading guide." }),
  })
  const report = publication.report
  const museReviews = [...(report.museReviews ?? []).filter((review) => review.stage !== "guide"), ...response.review === null ? [] : [response.review]]
  const reviewed = museReviews.length === 0 ? {} : { museReviews }
  const checks = report.checks.filter((check) => check.stage !== "guide")
  let guided: AssembledDocument
  if (response._tag === "accepted") {
    const guide = { ...response.value, providerAttemptId: response.receipt.id }
    const delivery = deliveryFor(claim, response.receipt)
    guided = {
      ...publication,
      canonical: { ...publication.canonical, guide },
      report: {
        ...report, ...reviewed,
        receipts: [...report.receipts.filter(({ receipt }) => receipt.id !== response.receipt.id), { delivery, receipt: response.receipt }],
        checks: [...checks, { stage, checkedPageIds: pageIds, result: "passed" }],
      },

} else {
  if (response.review === null) return yield* executionFailure("invalid-provider-response", response.reason)
  const issues = report.issues.filter((issue) => issue.stage !== "guide")
  guided = { ...publication, report: { ...report, ...reviewed, issues: [...issues, ...fallbackIssue(response.review, publication.extraction)], checks: [...checks, { stage, checkedPageIds: pageIds, result: "issues" }] } }

  const saved = yield* save(claim, guided)
  yield* progress(claim, stage, 1, 1)
  return { ...assembled, publication: saved }
})

const exportAndPublish = Effect.fnUntraced(function* (claim: DispatchClaim, input: Checkpoint) {
  const { publication } = yield* loadAssembled(claim, input)
  if (claim.run.configuration.guide !== undefined && publication.canonical.guide === undefined && !museFallback(publication.report.museReviews, "guide")) {
    return yield* executionFailure("invalid-provider-response", "The required reading guide is missing")
  }
  const available = publication.canonical.figures.flatMap(({ asset }) => asset._tag === "available" ? [[asset.artifact.path, asset.artifact] as const] : [])
  const imageArtifacts = [...new Map(available).values()]
  const figureAssets = yield* Effect.forEach(imageArtifacts, (artifact) => readPrivate(claim, artifact).pipe(Effect.map((bytes) => ({ artifact, bytes }))))
  yield* progress(claim, "export", 0, 1)
  const exported = yield* exportDocument(publication, figureAssets).pipe(Effect.provideService(Crypto.Crypto, crypto))

})

const stageHandlers = {
  extraction: extract, "page-check": checkPages, headings: classifyHeadings, figures: describeFigures,
  assembly: assemble, guide: writeGuide, export: exportAndPublish,
} satisfies Record<typeof Stage.Type, (claim: DispatchClaim, input: Checkpoint) => Effect.Effect<Checkpoint, unknown>>

const execute = Effect.fn("NormalizationStages.execute")(function* (claim: DispatchClaim, stage: typeof Stage.Type, input: Checkpoint) {
  if (!metaRuntimeConfiguration(claim.run.configuration)) {
    return yield* executionFailure("processing-unavailable", "This runtime permits only Meta model processing; historical non-Meta outputs remain readable")
  }
  if (input.documentId !== claim.document.id || input.runId !== claim.run.id) {
    return yield* executionFailure("conflict", "The workflow checkpoint belongs to another run")
  }
  const savedDocument = yield* documents.detail(claim.document.ownerId, claim.document.id)
  if (savedDocument.latestRun.id !== claim.run.id || !metaRuntimeConfiguration(savedDocument.latestRun.configuration)) {
    return yield* executionFailure("processing-unavailable", "The saved run is not eligible for this Meta-only runtime")
  }
  return yield* stageHandlers[stage](claim, input)

const retryable = ["provider-unknown-completion", "provider-failed", "storage-failed"].includes(code)
const message = known ? cause.message : "The processing output did not pass validation"
return new WorkflowStageFailure({ failure: { code, message, retryable, stage, pageId: null, figureId: null } })

export const runGuardPolicy = (policy: GuardPolicy, configuration: typeof RunConfiguration.Type): GuardPolicy => {
  if (configuration.guide !== undefined || policy.maximumCostMicrousd.guide === undefined) return policy
  const { guide: _guide, ...maximumCostMicrousd } = policy.maximumCostMicrousd
  return { ...policy, maximumCostMicrousd }
}

if (operation === "preview") {
  if (Option.isNone(renderer)) return yield* errorResponse("processing-unavailable", "Original page previews are unavailable. Download the original PDF instead.")
  const render = renderer.value.render
  const { document, privatePath } = yield* store.originalFile(session.user.id, id)
  const PageNumber = Schema.NumberFromString.check(Schema.isInt(), Schema.isBetween({ minimum: 1, maximum: document.pageCount }))
  const pageNumber = yield* Schema.decodeUnknownEffect(PageNumber)(new URL(request.url).searchParams.get("page"))
    .pipe(Effect.mapError(() => new UploadInputError({ code: "invalid-input", message: "Choose a page in this document." })))
  const tooSlow = () => errorResponse("processing-unavailable", "The original page preview took too long. Try again or download the original PDF.")
  const preview = yield* Effect.gen(function* () {
    const directory = yield* fs.makeTempDirectoryScoped({ directory: options.temporaryDirectory, prefix: "preview-" })
    yield* fs.chmod(directory, 0o700)
    const { byteCount, sourceHash, pageCount } = document
    const pages = yield* render({ privatePath, byteCount, sourceHash, pageCount, outputDirectory: directory, pageNumber })
    const page = pages[0]
    if (page === undefined) return yield* errorResponse("processing-unavailable", "Original page preview unavailable.")
    const image = yield* fs.readFile(path.join(directory, page.image.path))
    yield* store.detail(session.user.id, id)
    return new Response(image, { headers: { "content-type": "image/png", "content-length": String(image.byteLength) } })
  }).pipe(Effect.scoped, Effect.timeoutOrElse({ duration: "20 seconds", orElse: tooSlow }), previews.withPermitsIfAvailable(1))
  return Option.isSome(preview) ? preview.value : yield* errorResponse("queue-full", "Another original page is loading. Try again shortly.")
}

originalFile: Effect.fn("DocumentStore.originalFile")(function* (ownerId, documentId) {
  const { document } = yield* detail(ownerId, documentId)
  return { document, privatePath: yield* files.sourcePath(document) }
}),

const sourcePath = Effect.fn("SourceFiles.sourcePath")(function* (document: Document) {
  if ((yield* fs.realPath(directory(document.id)).pipe(Effect.mapError(mapError))) !== directory(document.id)) return yield* mapError("Document storage cannot follow a symlink")
  return path.join(directory(document.id), "source.pdf")
})

import {
  ArtifactManifest, CanonicalDocument, Extraction, ImageManifest, ProcessingReport, RatingValue, Run,
  matchesStoredReceipt, validatePublication, validateRunTransition,
  type DocumentId, type OutputRevisionId, type RunId, type StageReceipt, type UserId,
} from "../domain/index.ts"

export const Publication = Schema.Struct({
  extraction: Extraction, canonical: CanonicalDocument, images: ImageManifest, manifest: ArtifactManifest, report: ProcessingReport,
})

const encodeRun = (run: Run) => Schema.encodeEffect(Schema.fromJsonString(Run))(run).pipe(Effect.mapError(invalid))
const publishedJson = (publication: Publication, path: string) => {
  if (path === "document.json") return publication.canonical
  if (path === "images.json") return publication.images
  return path === "processing-report.json" ? publication.report : undefined
}
const durableAcceptance = (receipt: StageReceipt, saved: { readonly status: string; readonly validation_state: string | null }) =>
  receipt.state._tag !== "completed" || receipt.state.validation._tag !== "accepted" || saved.status === "completed" && saved.validation_state === "accepted"

const { scope } = manifest
if (scope.documentId !== documentId || scope.revisionId !== revisionId || scope.runId !== row.run_id) {
  return yield* invalid("Manifest scope does not match its publication")
}

const verifyStoredJson = Effect.fnUntraced(function* (ownerId: UserId, documentId: DocumentId, publication: Publication) {
  for (const entry of publication.manifest.entries) {
    const bytes = yield* artifacts.read(ownerId, documentId, { hash: entry.hash, byteCount: entry.byteCount })
    const expected = publishedJson(publication, entry.path)
    if (expected !== undefined && !sameBytes(bytes, jsonBytes(expected))) return yield* invalid("Stored JSON bytes differ from the publication")
  }
})
const insertOutput = (connection: Kysely<ApplicationDatabase>, documentId: DocumentId, run: Run, publication: Publication) =>
  query("publish-output", () => connection.insertInto("outputs").values({
    revision_id: publication.canonical.scope.revisionId, document_id: documentId, run_id: run.id, manifest_json: JSON.stringify(publication.manifest),
  }).execute())

const run = yield* decode(Run, { ...current, state: {
  _tag: publication.report.issues.length > 0 ? "succeeded-with-issues" : "succeeded", startedAt: current.state.startedAt,
  finishedAt: DateTime.formatIso(DateTime.makeUnsafe(now)), revisionId: publication.canonical.scope.revisionId,
} })

if (saved === undefined || !matchesStoredReceipt(saved.receipt_json, receipt) || !durableAcceptance(receipt, saved)) {
  return yield* invalid("Report receipt differs from its durable provider record")
}
if (receipt.id === publication.canonical.guide?.providerAttemptId) {
  if (saved.response_json === null) return yield* invalid("The guide provider response is missing")
  const response = yield* decode(Schema.fromJsonString(Schema.Json), saved.response_json)
  yield* verifySavedGuide(publication.canonical, receipt, response).pipe(Effect.provideService(Crypto.Crypto, crypto), Effect.mapError(invalid))
}

    return run
  }))
})
const publishRepair = Effect.fn("OutputStore.publishRepair")(function* (target: RepairTarget, input: Run, inputPublication: Publication) {
  const run = yield* decode(Run, input)
  const publication = yield* decode(Publication, inputPublication)
  if (publication.report.codeClassificationRepair === undefined) return yield* invalid("Only code-classification repairs use the maintenance publisher")
  const { document } = yield* documents.detail(target.ownerId, target.documentId)
  const violations = validatePublication({ document, run, ...publication })
  if (violations.length > 0) return yield* invalid(violations)
  yield* verifyStoredJson(target.ownerId, target.documentId, publication)
  const mastraRunId = run.mastraRunId
  if (mastraRunId === null) return yield* invalid("A repair run requires its local workflow identity")
  const runJson = yield* encodeRun(run)
  return yield* transaction((connection) => Effect.gen(function* () {
    const now = yield* Clock.currentTimeMillis
    const active = yield* query("repair-idle", () => connection.selectFrom("runs").select("id")
      .where("state", "in", ["queued", "running"]).executeTakeFirst())
    if (active !== undefined) return yield* storageConflict("code-repair", "Finish queued and running work before repairing code labels")
    const current = yield* query("repair-fence", () => connection.selectFrom("documents").select("id")
      .where("id", "=", target.documentId).where("owner_id", "=", target.ownerId).where("lifecycle", "=", "active")
      .where("expires_at", ">", now).where("latest_run_id", "=", target.replacedRunId).executeTakeFirst())
    if (current === undefined) return yield* storageConflict("code-repair", "Document changed while preparing the repair")
    yield* query("repair-run", () => connection.insertInto("runs").values({
      id: run.id, document_id: target.documentId, owner_id: target.ownerId, state: run.state._tag, mastra_run_id: mastraRunId, run_json: runJson,
      created_at: DateTime.toEpochMillis(DateTime.makeUnsafe(run.createdAt)), claim_token: null, worker_id: null, lease_expires_at: null,
    }).execute())
    yield* insertOutput(connection, target.documentId, run, publication)
    yield* query("repair-pointer", () => connection.updateTable("documents").set({ latest_run_id: run.id })
      .where("id", "=", target.documentId).where("latest_run_id", "=", target.replacedRunId).execute())

